,"name":"module_id","not_null":true,"type":"uuid"},{"default":null,"name":"user_id","not_null":true,"type":"uuid"},{"default":null,"name":"unlock_at","not_null":false,"type":"timestamp with time zone"},{"default":"now()","name":"created_at","not_null":true,"type":"timestamp with time zone"},{"default":"now()","name":"updated_at","not_null":true,"type":"timestamp with time zone"}],"constraints":[{"definition":"FOREIGN KEY (module_id) REFERENCES course_modules(id) ON DELETE CASCADE","name":"module_access_overrides_module_id_fkey","type":"f"},{"definition":"UNIQUE (module_id, user_id)","name":"module_access_overrides_module_id_user_id_key","type":"u"},{"definition":"PRIMARY KEY (id)","name":"module_access_overrides_pkey","type":"p"}],"policies":[{"command":"*","name":"Admins manage all module overrides","permissive":true,"roles":["PUBLIC"],"using":"has_role('admin'::app_role, auth.uid())","with_check":"has_role('admin'::app_role, auth.uid())"},{"command":"*","name":"Org manages module overrides of own courses","permissive":true,"roles":["PUBLIC"],"using":"(EXISTS ( SELECT 1\n   FROM (course_modules m\n     JOIN courses c ON ((c.id = m.course_id)))\n  WHERE ((m.id = module_access_overrides.module_id) AND (c.organization_id = current_organization_id()))))","with_check":"(EXISTS ( SELECT 1\n   FROM (course_modules m\n     JOIN courses c ON ((c.id = m.course_id)))\n  WHERE ((m.id = module_access_overrides.module_id) AND (c.organization_id = current_organization_id()))))"},{"command":"r","name":"Students read own module overrides","permissive":true,"roles":["PUBLIC"],"using":"(user_id = auth.uid())","with_check":null},{"command":"*","name":"account_deletion_no_revoked_access","permissive":false,"roles":["authenticated"],"using":"( SELECT account_deletion_access_allowed() AS account_deletion_access_allowed)","with_check":"( SELECT account_deletion_access_allowed() AS account_deletion_access_allowed)"}],"triggers":[{"name":"account_deletion_subject_fence","definition":"CREATE TRIGGER account_deletion_subject_fence BEFORE INSERT OR UPDATE ON public.module_access_overrides FOR EACH ROW EXECUTE FUNCTION account_deletion_subject_write_guard('user_id')","enabled":"O"},{"name":"trg_mao_updated_at","definition":"CREATE TRIGGER trg_mao_updated_at BEFORE UPDATE ON public.module_access_overrides FOR EACH ROW EXECUTE FUNCTION update_updated_at_column()","enabled":"O"}]},{"name":"module_access_schedules","owner":"postgres","acl":"{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres,sandbox_exec_atxwvjxbqjgkbjlhsdch=ar/postgres,sandbox_exec=ar/postgres}","rls":true,"force_rls":false,"columns":[{"default":"gen_random_uuid()","name":"id","not_null":true,"type":"uuid"},{"default":null,"name":"module_id","not_null":true,"type":"uuid"},{"default":null,"name":"course_id","not_null":true,"type":"uuid"},{"default":null,"name":"unlock_at","not_null":true,"type":"timestamp with time zone"},{"default":"now()","name":"created_at","not_null":true,"type":"timestamp with time zone"},{"default":"now()","name":"updated_at","not_null":true,"type":"timestamp with time zone"}],"constraints":[{"definition":"FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE","name":"module_access_schedules_course_id_fkey","type":"f"},{"definition":"FOREIGN KEY (module_id) REFERENCES course_modules(id) ON DELETE CASCADE","name":"module_access_schedules_module_id_fkey","type":"f"},{"definition":"UNIQUE (module_id)","name":"module_access_schedules_module_id_key","type":"u"},{"definition":"PRIMARY KEY (id)","name":"module_access_schedules_pkey","type":"p"}],"policies":[{"command":"*","name":"Admins manage all module schedules","permissive":true,"roles":["PUBLIC"],"using":"has_role('admin'::app_role, auth.uid())","with_check":"has_role('admin'::app_role, auth.uid())"},{"command":"r","name":"Enrolled students read module schedules","permissive":true,"roles":["PUBLIC"],"using":"(EXISTS ( SELECT 1\n   FROM enrollments e\n  WHERE ((e.course_id = module_access_schedules.course_id) AND (e.user_id = auth.uid()))))","with_check":null},{"command":"*","name":"Org manages module schedules of own courses","permissive":true,"roles":["PUBLIC"],"using":"(EXISTS ( SELECT 1\n   FROM courses c\n  WHERE ((c.id = module_access_schedules.course_id) AND (c.organization_id = current_organization_id()))))","with_check":"(EXISTS ( SELECT 1\n   FROM courses c\n  WHERE ((c.id = module_access_schedules.course_id) AND (c.organization_id = current_organization_id()))))"},{"command":"*","name":"account_deletion_no_revoked_access","permissive":false,"roles":["authenticated"],"using":"( SELECT account_deletion_access_allowed() AS account_deletion_access_allowed)","with_check":"( SELECT account_deletion_access_allowed() AS account_deletion_access_allowed)"}],"triggers":[{"name":"trg_mas_updated_at","definition":"CREATE TRIGGER trg_mas_updated_at BEFORE UPDATE ON public.module_access_schedules FOR EACH ROW EXECUTE FUNCTION update_updated_at_column()","enabled":"O"}]}],"functions":[{"signature":"public.account_deletion_subject_write_guard()","definition_md5":"cd0003cc49bdf9a3d074c9e624146e46"},{"signature":"public.invalidate_marketplace_course_validation()","definition_md5":"b19482763a8cbda7b9df4be01a51ba9d"},{"signature":"public.update_updated_at_column()","definition_md5":"3210625d1c794f6db7b3c3defc5984dd"}]}$module_proof$;r jsonb;f jsonb;actual jsonb;
BEGIN
 IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='module_write_guard_allowed')
 OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid IN('public.course_modules'::regclass,'public.module_access_schedules'::regclass,'public.module_access_overrides'::regclass) AND polname IN('module_write_guard_insert','module_write_guard_update','module_write_guard_delete','module_schedule_write_guard_insert','module_schedule_write_guard_update','module_schedule_write_guard_delete','module_override_write_guard_insert','module_override_write_guard_update','module_override_write_guard_delete')) THEN
  RAISE EXCEPTION 'MODULE_WRITE_GUARD_NAME_COLLISION';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated' AND NOT rolsuper AND NOT rolbypassrls) THEN RAISE EXCEPTION 'MODULE_WRITE_GUARD_AUTH_ROLE_CHANGED';END IF;
 IF to_regprocedure('public.lesson_write_guard_allowed(uuid)') IS NULL OR md5(pg_get_functiondef('public.lesson_write_guard_allowed(uuid)'::regprocedure)) IS DISTINCT FROM proof->>'lesson_guard_definition_md5' THEN RAISE EXCEPTION 'MODULE_WRITE_GUARD_LESSON_PREDICATE_CHANGED';END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(proof->'functions') LOOP
  IF to_regprocedure(f->>'signature') IS NULL OR md5(pg_get_functiondef(to_regprocedure(f->>'signature'))) IS DISTINCT FROM f->>'definition_md5' THEN RAISE EXCEPTION 'MODULE_WRITE_GUARD_DEPENDENCY_CHANGED:%',f->>'signature';END IF;
 END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(proof->'relations') LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=to_regclass('public.'||(r->>'name')) AND c.relrowsecurity=(r->>'rls')::boolean AND c.relforcerowsecurity=(r->>'force_rls')::boolean AND pg_get_userbyid(c.relowner)=r->>'owner' AND c.relacl::text=r->>'acl') THEN RAISE EXCEPTION 'MODULE_WRITE_GUARD_TABLE_CHANGED:%',r->>'name';END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum),'[]') INTO actual FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=to_regclass('public.'||(r->>'name')) AND a.attnum>0 AND NOT a.attisdropped;
  IF actual IS DISTINCT FROM r->'columns' THEN RAISE EXCEPTION 'MODULE_WRITE_GUARD_COLUMNS_CHANGED:%',r->>'name';END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('name',conname,'type',contype,'definition',pg_get_constraintdef(oid)) ORDER BY conname),'[]') INTO actual FROM pg_constraint WHERE conrelid=to_regclass('public.'||(r->>'name'));
  IF actual IS DISTINCT FROM r->'constraints' THEN RAISE EXCEPTION 'MODULE_WRITE_GUARD_CONSTRAINTS_CHANGED:%',r->>'name';END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',(SELECT jsonb_agg(CASE WHEN role_id=0 THEN 'PUBLIC' ELSE pg_get_userbyid(role_id)::text END ORDER BY CASE WHEN role_id=0 THEN 'PUBLIC' ELSE pg_get_userbyid(role_id)::text END) FROM unnest(p.polroles) role_id),'using',pg_get_expr(p.polqual,p.polrelid),'with_check',pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY p.polname),'[]') INTO actual FROM pg_policy p WHERE p.polrelid=to_regclass('public.'||(r->>'name'));
  IF actual IS DISTINCT FROM r->'policies' THEN RAISE EXCEPTION 'MODULE_WRITE_GUARD_POLICIES_CHANGED:%',r->>'name';END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled) ORDER BY t.tgname),'[]') INTO actual FROM pg_trigger t WHERE t.tgrelid=to_regclass('public.'||(r->>'name')) AND NOT t.tgisinternal;
  IF actual IS DISTINCT FROM r->'triggers' THEN RAISE EXCEPTION 'MODULE_WRITE_GUARD_TRIGGERS_CHANGED:%',r->>'name';END IF;
 END LOOP;
END;$preflight$;

-- Resolve the authoritative course without depending on caller SELECT visibility.
-- NULL expected-course means permission on the actual module's course only.
-- Non-NULL expected-course additionally proves the new schedule pair is consistent.
CREATE FUNCTION public.module_write_guard_allowed(p_module_id uuid,p_expected_course_id uuid DEFAULT NULL)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
 SELECT coalesce(EXISTS(SELECT 1 FROM public.course_modules m
  WHERE m.id=p_module_id AND (p_expected_course_id IS NULL OR m.course_id=p_expected_course_id)
  AND public.lesson_write_guard_allowed(m.course_id)),false)
$fn$;
DO $new_acl$ DECLARE g record;fn regprocedure:='public.module_write_guard_allowed(uuid,uuid)'::regprocedure;BEGIN
 FOR g IN SELECT DISTINCT a.grantee FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=fn AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION public.module_write_guard_allowed(uuid,uuid) FROM %s CASCADE',CASE WHEN g.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(g.grantee)) END);
 END LOOP;
END;$new_acl$;
GRANT EXECUTE ON FUNCTION public.module_write_guard_allowed(uuid,uuid) TO authenticated;

CREATE POLICY module_write_guard_insert ON public.course_modules AS RESTRICTIVE FOR INSERT TO PUBLIC
 WITH CHECK(public.lesson_write_guard_allowed(course_id));
CREATE POLICY module_write_guard_update ON public.course_modules AS RESTRICTIVE FOR UPDATE TO PUBLIC
 USING(public.lesson_write_guard_allowed(course_id)) WITH CHECK(public.lesson_write_guard_allowed(course_id));
CREATE POLICY module_write_guard_delete ON public.course_modules AS RESTRICTIVE FOR DELETE TO PUBLIC
 USING(public.lesson_write_guard_allowed(course_id));

CREATE POLICY module_schedule_write_guard_insert ON public.module_access_schedules AS RESTRICTIVE FOR INSERT TO PUBLIC
 WITH CHECK(public.module_write_guard_allowed(module_id,course_id));
-- The stored and authoritative course may differ after a module reparent.
-- Old-row repair/delete requires write permission on BOTH courses; a new value
-- must always be consistent. No implicit repair or reparent trigger is added.
CREATE POLICY module_schedule_write_guard_update ON public.module_access_schedules AS RESTRICTIVE FOR UPDATE TO PUBLIC
 USING(public.module_write_guard_allowed(module_id,NULL) AND public.lesson_write_guard_allowed(course_id))
 WITH CHECK(public.module_write_guard_allowed(module_id,course_id));
CREATE POLICY module_schedule_write_guard_delete ON public.module_access_schedules AS RESTRICTIVE FOR DELETE TO PUBLIC
 USING(public.module_write_guard_allowed(module_id,NULL) AND public.lesson_write_guard_allowed(course_id));

CREATE POLICY module_override_write_guard_insert ON public.module_access_overrides AS RESTRICTIVE FOR INSERT TO PUBLIC
 WITH CHECK(public.module_write_guard_allowed(module_id,NULL));
CREATE POLICY module_override_write_guard_update ON public.module_access_overrides AS RESTRICTIVE FOR UPDATE TO PUBLIC
 USING(public.module_write_guard_allowed(module_id,NULL)) WITH CHECK(public.module_write_guard_allowed(module_id,NULL));
CREATE POLICY module_override_write_guard_delete ON public.module_access_overrides AS RESTRICTIVE FOR DELETE TO PUBLIC
 USING(public.module_write_guard_allowed(module_id,NULL));
